from typing import List
import heapq

class Solution:

	def kthLargest(self, N: int, K: int, Arr: List[int]) -> int:
		res = []
		size = K
		for i in range(N):
			sum = 0
			for j in range(i, N):
				sum = sum + Arr[j]
				if size:
					heapq.heappush(res, sum)
					size = size - 1
				elif res[0] < sum:
					heapq.heappop(res)
					heapq.heappush(res, sum)
		return res[0]
